CREATE    PROCEDURE [synapse_ce].[usp_Update_rics_surveyanswer]
AS
BEGIN
	UPDATE tgt SET 
		tgt.[createdby] = stg.[createdby],
		tgt.[createdby_entitytype] = stg.[createdby_entitytype],
		tgt.[createdbyname] = stg.[createdbyname],
		tgt.[createdbyyominame] = stg.[createdbyyominame],
		tgt.[createdon] = stg.[createdon],
		--tgt.[createdonbehalfby] = stg.[createdonbehalfby],
		--tgt.[createdonbehalfby_entitytype] = stg.[createdonbehalfby_entitytype],
		--tgt.[createdonbehalfbyname] = stg.[createdonbehalfbyname],
		--tgt.[createdonbehalfbyyominame] = stg.[createdonbehalfbyyominame],
		--tgt.[importsequencenumber] = stg.[importsequencenumber],
		tgt.[modifiedby] = stg.[modifiedby],
		tgt.[modifiedby_entitytype] = stg.[modifiedby_entitytype],
		tgt.[modifiedbyname] = stg.[modifiedbyname],
		tgt.[modifiedbyyominame] = stg.[modifiedbyyominame],
		tgt.[modifiedon] = stg.[modifiedon],
		--tgt.[modifiedonbehalfby] = stg.[modifiedonbehalfby],
		--tgt.[modifiedonbehalfby_entitytype] = stg.[modifiedonbehalfby_entitytype],
		--tgt.[modifiedonbehalfbyname] = stg.[modifiedonbehalfbyname],
		--tgt.[modifiedonbehalfbyyominame] = stg.[modifiedonbehalfbyyominame],
		tgt.[overriddencreatedon] = stg.[overriddencreatedon],
		tgt.[ownerid] = stg.[ownerid],
		tgt.[ownerid_entitytype] = stg.[ownerid_entitytype],
		tgt.[owneridname] = stg.[owneridname],
		--tgt.[owneridtype] = stg.[owneridtype],
		tgt.[owneridyominame] = stg.[owneridyominame],
		tgt.[owningbusinessunit] = stg.[owningbusinessunit],
		tgt.[owningbusinessunit_entitytype] = stg.[owningbusinessunit_entitytype],
		tgt.[owningbusinessunitname] = stg.[owningbusinessunitname],
		--tgt.[owningteam] = stg.[owningteam],
		--tgt.[owningteam_entitytype] = stg.[owningteam_entitytype],
		tgt.[owninguser] = stg.[owninguser],
		tgt.[owninguser_entitytype] = stg.[owninguser_entitytype],
		tgt.[rics_additionalinformation] = stg.[rics_additionalinformation],
		tgt.[rics_answer] = stg.[rics_answer],
		tgt.[rics_answerstatus] = stg.[rics_answerstatus],
		tgt.[rics_evidencefilename] = stg.[rics_evidencefilename],
		tgt.[rics_evidencepath] = stg.[rics_evidencepath],
		tgt.[rics_heading] = stg.[rics_heading],
		tgt.[rics_heading_entitytype] = stg.[rics_heading_entitytype],
		tgt.[rics_headingname] = stg.[rics_headingname],
		tgt.[rics_name] = stg.[rics_name],
		--tgt.[rics_order] = stg.[rics_order],
		tgt.[rics_possibleanswer] = stg.[rics_possibleanswer],
		tgt.[rics_possibleanswer_entitytype] = stg.[rics_possibleanswer_entitytype],
		--tgt.[rics_possibleanswerconfig] = stg.[rics_possibleanswerconfig],
		--tgt.[rics_possibleanswerconfig_entitytype] = stg.[rics_possibleanswerconfig_entitytype],
		--tgt.[rics_possibleanswerconfigname] = stg.[rics_possibleanswerconfigname],
		tgt.[rics_possibleanswername] = stg.[rics_possibleanswername],
		tgt.[rics_question] = stg.[rics_question],
		tgt.[rics_question_entitytype] = stg.[rics_question_entitytype],
		tgt.[rics_questionname] = stg.[rics_questionname],
		tgt.[rics_questionset] = stg.[rics_questionset],
		tgt.[rics_questionset_entitytype] = stg.[rics_questionset_entitytype],
		--tgt.[rics_questionsetconfig] = stg.[rics_questionsetconfig],
		--tgt.[rics_questionsetconfig_entitytype] = stg.[rics_questionsetconfig_entitytype],
		--tgt.[rics_questionsetconfigname] = stg.[rics_questionsetconfigname],
		tgt.[rics_questionsetname] = stg.[rics_questionsetname],
		tgt.[rics_score] = stg.[rics_score],
		tgt.[rics_survey] = stg.[rics_survey],
		tgt.[rics_survey_entitytype] = stg.[rics_survey_entitytype],
		--tgt.[rics_surveyanswerid] = stg.[rics_surveyanswerid],
		tgt.[rics_surveyname] = stg.[rics_surveyname],
		tgt.[rics_surveyresponse] = stg.[rics_surveyresponse],
		tgt.[rics_surveyresponse_entitytype] = stg.[rics_surveyresponse_entitytype],
		tgt.[rics_surveyresponsename] = stg.[rics_surveyresponsename],
		tgt.[SinkCreatedOn] = stg.[SinkCreatedOn],
		tgt.[SinkModifiedOn] = stg.[SinkModifiedOn],
		tgt.[statecode] = stg.[statecode],
		tgt.[statuscode] = stg.[statuscode],
		--tgt.[timezoneruleversionnumber] = stg.[timezoneruleversionnumber],
		--tgt.[utcconversiontimezonecode] = stg.[utcconversiontimezonecode],
		tgt.[versionnumber] = stg.[versionnumber]
	 FROM [synapse_ce].[rics_surveyanswer] tgt
		INNER JOIN [staging_ce].[rics_surveyanswer] stg
			ON tgt.[id] = stg.[id]
END
